/*
 * A257909  Sequence (d(n)) generated by Rule 3 (in Comments) with a(1) = 0
 *          and d(1) = 2.
 * https://oeis.org/A257909
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, easy
 * Formula:   not stated
 * Range:     i8 n <= 145, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Rule 3 sequence d(n) with a(1)=0 and d(1)=2.
   Implements the algorithm described in OEIS A257909. The function
   returns the n‑th term d(n).  The computation is memoised and
   works for any order of calls. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* --- memory for the sequence --- */
static seq_t *a_buf   = NULL;            /* a(1), a(2), …     */
static seq_t *d_buf   = NULL;            /* d(1), d(2), …     */
static size_t buf_used = 0;              /* number of terms stored */
static size_t buf_cap  = 0;              /* capacity of buffers   */

/* linear search in a seq_t array */
static inline bool seq_in(const seq_t *arr, size_t len, seq_t val)
{
    for (size_t i = 0; i < len; ++i)
        if (arr[i] == val) return true;
    return false;
}

/* enlarge buffers to hold at least need elements */
static void ensure_capacity(size_t need)
{
    if (need <= buf_cap) return;
    size_t new_cap = buf_cap == 0 ? 16 : buf_cap * 2;
    while (new_cap < need) new_cap <<= 1;

    a_buf = (seq_t *)realloc(a_buf, new_cap * sizeof(seq_t));
    d_buf = (seq_t *)realloc(d_buf, new_cap * sizeof(seq_t));
    buf_cap = new_cap;
}

/* generate the next term of the sequence (append) */
static void generate_next(void)
{
    seq_t ak = a_buf[buf_used - 1];          /* current a(k) */
    seq_t h, dnext, anext;
    bool found = false;

    /* ----- Step 1: attempt negative h ----- */
    seq_t lower = (seq_t)(2 - ak);          /* inclusive lowest h (most negative) */
    if (lower <= -1) {
        for (h = lower; h <= -1; ++h) {
            if (seq_in(d_buf, buf_used, h)) continue;          /* h already used */
            seq_t newA = ak + h;
            if (seq_in(a_buf, buf_used, newA)) continue;        /* duplicate a */
            /* valid negative step */
            dnext = h;
            anext = newA;
            found = true;
            break;
        }
    }

    /* ----- Step 2: if no negative step, pick positive h ----- */
    if (!found) {
        seq_t hp = 1;
        for (;;) {
            if (seq_in(d_buf, buf_used, hp)) { ++hp; continue; }   /* already used */
            seq_t newA = ak + hp;
            /* a(k)-hp must not be in A(k) */
            if (!seq_in(a_buf, buf_used, ak - hp)) {
                dnext = hp;
                anext = newA;
                break;
            }
            ++hp;
        }
    }

    /* Append the new term */
    ensure_capacity(buf_used + 1);
    a_buf[buf_used] = anext;
    d_buf[buf_used] = dnext;
    ++buf_used;
}

/* ------------------------------------------------------------------ */

seq_t a(idx_t n)
{
    if (n <= 0) return 0;                       /* offset 1 – undefined for n=0 */

    /* initialise the first term */
    if (buf_used == 0) {
        ensure_capacity(1);
        a_buf[0] = (seq_t)0;                    /* a(1) = 0   */
        d_buf[0] = (seq_t)2;                    /* d(1) = 2   */
        buf_used = 1;
    }

    /* generate up to the requested index */
    while (buf_used < (size_t)n)
        generate_next();

    return d_buf[n - 1];                        /* d(n) is stored at index n-1 */
}
